import{_ as a,o as e,c as t,ai as o}from"./chunks/framework.DAbPic9L.js";const b=JSON.parse('{"title":"历世言-物我篇","description":"","frontmatter":{},"headers":[],"relativePath":"mybook/li-shi-yan/wu-wo.md","filePath":"mybook/li-shi-yan/wu-wo.md","lastUpdated":1787215730000}'),r={name:"mybook/li-shi-yan/wu-wo.md"};function s(i,p,n,_,l,d){return e(),t("div",null,[...p[0]||(p[0]=[o('<h1 id="历世言-物我篇" tabindex="-1">历世言-物我篇 <a class="header-anchor" href="#历世言-物我篇" aria-label="Permalink to &quot;历世言-物我篇&quot;">​</a></h1><p>文/晨风不可依米</p><br><p>道恒無念，恍惚無则，混沌有象，皆因由炁。</p><p>炁之化，积水则渊，积沙成塔，极境而思誠。</p><br><p>唯物，恒态；唯我，恒变。</p><p>取物予物象，取我而内观。</p><p>物我一统，则界由生。</p><br><p>唯物者，形异而混一，受道乃容；</p><p>唯我者，混同而合一，名异实同；</p><p>物我一界，道始誠然。</p><br><p>人誠，信也，则万物本根。</p><p>依天命，循地脉，勤人事。</p><p>负阴而抱阳，冲气以虚合，大器免成。</p><p>無形而以生，有理终所成，人道至始。</p><br><p>人誠道乎，悖伪道也，世人远乎。</p><p>非人言德，仁义礼制，世人不受。</p><p>先天之道，处道之所为，上古天真。</p><p>后天之道，行道之所径，众生娱乐。</p><p>既道非道，即道可盗；非人道，道可盗也。</p><br><p>物恒长存，混一，则合成理。</p><p>内观恍惚，合一，则混由象。</p><p>以物一观，可成一界；以我一观，可成万物。是以道論而观局，咸其感而自取也。</p><p>己非以诸君之界物，以观其論，道不同而非议。</p><p>然恒以論道之齐物，以局作观，道亦同而理成。</p><p>道論以局作观，非物無所用，非我無所取，近乎道矣。</p><p>道論以观作局，非物無所念，非我無所欲，近乎道矣。</p><p>道其悟者，以观其眇。道其論者，以口其徼。其出者谓同，而界物之器非也。</p><br><p>人常有欲，色音味心狂，六神不得全。德其所好，仁者有心，义事君宜，礼之貌情，制强盛弱。</p><p>今众生故此而失道，失德，失仁，失义，失礼，燃道也。</p><p>道恒無欲，生有而無念，其象俱精藏。物我一取，五色不盲，五音不乱，五味不爽，虚心实肉。</p><p>处古今皆此恒常在，無德，無仁，無义，無礼，近道也。</p><br><p>人欲有际限，道妙無瀚徼。</p><p>以人欲观道妙，觉有情，不见其形，殆也。</p><p>以道妙观人欲，非有情，终见姚善，伪也。</p><p>人可拈道，人欲而道也。人求道来，君息远道也。</p><p>众生曰道，日以心斗，上下伐欺。道之人誠，信为本根，悖道而盗道，同鸠而鸣，司道噬食。</p><p>上古从道，应以四时，万物序局。朴道無锋，俱精宰真，结道而得道，同天而地，寒暑一炁。</p>',45)])])}const m=a(r,[["render",s]]);export{b as __pageData,m as default};
